#include "studio_pair_query_recreation_candidate.h"
#include <array>
#include <cassert>
#include <cstdio>
struct Query{unsigned id;};struct State{unsigned receiver;};struct Owner{int32_t queryCapability;std::array<Query*,2> queries;std::array<unsigned char,2> active;};
struct Services{State state{1};Query query{1};int32_t publishedCapability;uint32_t result;bool replace;unsigned textures=0,flushes=0,creates=0,issues=0,warnings=0;bool diagnosticEnabled(){return false;}void diagnostic(){}void recreateTexture(Owner& o){++textures;o.queryCapability=publishedCapability;}State* commandState(){return &state;}void flush(State*){++flushes;if(replace)state.receiver=2;}unsigned* device(State* s){return &s->receiver;}uint32_t createQuery(unsigned* receiver,unsigned type,Query*& output){assert(*receiver==(replace?2u:1u)&&type==8);++creates;output=&query;return result;}void queryUnavailable(){++warnings;}void issue(Query* q,unsigned flags){assert(q==&query&&flags==1);++issues;}};
int main(){unsigned cases=0;for(int32_t cap:{-1,0,1,2})for(uint32_t result:{0u,1u,0x8876086au,0x80004005u})for(bool replace:{false,true}){Owner owner{99,{nullptr,nullptr},{7,8}};Services s;s.publishedCapability=cap;s.result=result;s.replace=replace;studioPairQueryRecreationCandidate(owner,s);assert(s.textures==1);if(cap==0){assert(!s.creates&&!s.issues&&!s.flushes&&!owner.queries[0]&&!owner.queries[1]&&owner.active[0]==0&&owner.active[1]==0);}else{assert(s.creates==2&&s.flushes==2&&owner.queries[0]==&s.query&&owner.queries[1]==&s.query);if(result==0x8876086a){assert(s.warnings==2&&!s.issues&&owner.active[0]==7&&owner.active[1]==8);}else{assert(!s.warnings&&s.issues==2&&owner.active[0]==1&&owner.active[1]==1);}}++cases;}std::printf("pair_query_recreation_cases=%u passed\n",cases);}
